import SwiftUI

struct AchievementUnlockBannerView: View {

    let message: String
    let onDismiss: () -> Void

    // MARK: - Achievement Information

    private struct AchievementBadge: Identifiable {

        let tier: String
        let name: String

        var id: String {
            "\(tier):\(name)"
        }
    }

    // MARK: - Extract Achievement Names

    private var badges: [AchievementBadge] {

        let lines = message.components(separatedBy: "\n")

        return lines.compactMap { line in

            for tier in ["Bronze", "Silver", "Gold"] {

                let prefix = "\(tier) - "

                if line.hasPrefix(prefix) {

                    return AchievementBadge(
                        tier: tier,
                        name: String(line.dropFirst(prefix.count))
                    )
                }
            }

            return nil
        }
    }

    // MARK: - Extract Reward Summary

    private var rewardSummary: String? {

        message
            .components(separatedBy: "\n")
            .first {
                $0.hasPrefix("+") && $0.contains("XP")
            }
    }

    // MARK: - Banner

    var body: some View {

        VStack(alignment: .leading, spacing: 12) {

            // MARK: - Header

            HStack(spacing: 10) {

                Image(systemName: "trophy.fill")
                    .font(.title2)
                    .foregroundStyle(.yellow)

                Text(
                    badges.count > 1
                    ? "\(badges.count) Achievements Unlocked!"
                    : "Achievement Unlocked!"
                )
                .font(.headline)

                Spacer()

                Button(action: onDismiss) {

                    Image(systemName: "xmark.circle.fill")
                        .foregroundStyle(.secondary)
                        .font(.title3)
                }
                .buttonStyle(.plain)
                .accessibilityLabel("Dismiss achievement notification")
            }

            // MARK: - Achievement Badges

            if badges.isEmpty {

                Text(message)
                    .font(.subheadline)

            } else {

                // Display up to three achievements
                ForEach(Array(badges.prefix(3))) { badge in

                    HStack(spacing: 12) {

                        Image(systemName: "medal.fill")
                            .font(.title2)
                            .foregroundStyle(
                                tierColor(for: badge.tier)
                            )
                            .frame(width: 35)

                        VStack(alignment: .leading, spacing: 4) {

                            Text(badge.name)
                                .font(.subheadline)
                                .fontWeight(.semibold)

                            Text(badge.tier.uppercased())
                                .font(.caption2)
                                .fontWeight(.bold)
                                .foregroundStyle(
                                    tierColor(for: badge.tier)
                                )
                        }

                        Spacer()
                    }
                }

                // Keep the banner compact if many unlock together
                if badges.count > 3 {

                    Text(
                        "+\(badges.count - 3) more achievements unlocked"
                    )
                    .font(.caption)
                    .foregroundStyle(.secondary)
                }

                // MARK: - Rewards

                if let rewardSummary {

                    Divider()

                    Label(
                        rewardSummary,
                        systemImage: "star.fill"
                    )
                    .font(.caption)
                    .fontWeight(.medium)
                }
            }
        }
        .padding()
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            .regularMaterial,
            in: RoundedRectangle(cornerRadius: 16)
        )
        .overlay {

            RoundedRectangle(cornerRadius: 16)
                .strokeBorder(
                    Color.primary.opacity(0.1),
                    lineWidth: 1
                )
        }
        .shadow(
            color: .black.opacity(0.08),
            radius: 8,
            y: 3
        )
    }

    // MARK: - Achievement Tier Colors

    private func tierColor(for tier: String) -> Color {

        switch tier {

        case "Bronze":
            return .brown

        case "Silver":
            return .gray

        case "Gold":
            return .yellow

        default:
            return .secondary
        }
    }

} // Closes AchievementUnlockBannerView

